#include <bits/stdc++.h>
using namespace std;

const int Maxn = (1 << 19) + 5;
int n, k, p, maxVal, popCount[Maxn], f[Maxn];
int tmp1[20][Maxn], tmp2[20][Maxn], tmp3[20][Maxn];
long long mod2;
long long t[20][Maxn];
long long fact[Maxn], invFact[Maxn];

long long modPow(long long base, long long exp) {
    long long result = 1;
    base %= p;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % p;
        base = (base * base) % p;
        exp >>= 1;
    }
    return result;
}

void precompute() {
    fact[0] = 1;
    for (int i = 1; i <= maxVal; ++i)
        fact[i] = fact[i-1] * i % p;
    invFact[maxVal] = modPow(fact[maxVal], p - 2);
    for (int i = maxVal - 1; i >= 0; --i)
        invFact[i] = invFact[i+1] * (i+1) % p;
}

int nextPowerOfTwo(int x) {
    int power = 1;
    while (power < x) power <<= 1;
    return power;
}

void fwTransform(int *arr, int len, bool inverse = false) {
    static long long buffer[Maxn];
    for (int i = 0; i < len; ++i) buffer[i] = arr[i];

    if (inverse) {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += (step << 1)) {
                for (int j = 0; j < step; ++j) {
                    buffer[i + j + step] = (buffer[i + j + step] - buffer[i + j] % p + p) % p;
                }
            }
        }
    } else {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += (step << 1)) {
                for (int j = 0; j < step; ++j) {
                    buffer[i + j + step] = (buffer[i + j + step] + buffer[i + j]) % p;
                }
            }
        }
    }

    for (int i = 0; i < len; ++i) {
        arr[i] = (int)(buffer[i] % p);
        if (arr[i] < 0) arr[i] += p;
    }
}

inline void adjust(long long &x) {
    if (x >= mod2) x -= mod2;
}

void multiply() {
    for (int i = 0; i <= 19; ++i) {
        memset(tmp1[i], 0, sizeof(int[maxVal + 1]));
        memset(t[i], 0, sizeof(long long[maxVal + 1]));
    }

    for (int i = 0; i <= maxVal; ++i)
        tmp1[popCount[i]][i] = f[i];

    for (int i = 0; i <= 19; ++i)
        fwTransform(tmp1[i], maxVal + 1);

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= maxVal; ++s)
                adjust(t[q + l][s] += 1LL * tmp1[q][s] * tmp2[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= maxVal; ++s)
            tmp3[q][s] = (int)(t[q][s] % p);

    for (int i = 0; i <= 19; ++i)
        fwTransform(tmp3[i], maxVal + 1, true);

    for (int i = 0; i <= maxVal; ++i)
        f[i] = tmp3[popCount[i]][i];
}

void squareTransform() {
    static int buffer[20][Maxn];
    for (int i = 0; i <= 19; ++i)
        memset(t[i], 0, sizeof(long long[maxVal + 1]));

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= maxVal; ++s)
                adjust(t[q + l][s] += 1LL * tmp2[q][s] * tmp2[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= maxVal; ++s)
            buffer[q][s] = (int)(t[q][s] % p);

    for (int i = 0; i <= 19; ++i)
        fwTransform(buffer[i], maxVal + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(tmp2[i], 0, sizeof(int[maxVal + 1]));

    for (int i = 0; i <= maxVal; ++i)
        tmp2[popCount[i]][i] = buffer[popCount[i]][i];

    for (int i = 0; i <= 19; ++i)
        fwTransform(tmp2[i], maxVal + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    mod2 = 1LL * p * p;

    if (n & 1) {
        printf("%lld", modPow(k, n));
        return 0;
    }

    f[0] = 1;
    maxVal = nextPowerOfTwo(n + 1) - 1;
    precompute();

    for (int i = 0; i <= maxVal; ++i)
        popCount[i] = __builtin_popcount(i);

    for (int i = 0; i <= maxVal; ++i)
        tmp2[popCount[i]][i] = invFact[i];

    for (int i = 0; i <= 19; ++i)
        fwTransform(tmp2[i], maxVal + 1);

    int originalK = k;
    while (k) {
        if (k & 1) multiply();
        k >>= 1;
        if (k) squareTransform();
    }

    printf("%lld", (modPow(originalK, n) - fact[n] * f[n] % p + p) % p);
    return 0;
}
